func countdown(n int) {
    if n == 0 {
        fmt.Println("liftoff")
    } else {
        fmt.Println(n)
        countdown(n-1)
    }
}

func factorial(n int) int {
    if n <= 1 {
        return 1
    }
    return n * factorial(n-1)
}

