func trace(n int) {
    if n > 0 {
        fmt.Println("in", n)
        trace(n-1)
        fmt.Println("out", n)
    }
}

func gcd(a, b int) int {
    if b == 0 {
        return a
    }
    return gcd(b, a%b)
}

